insert into public.food_sources (id, title, method, url) values ('S1', 'safefood, What''s in your Indian takeaway? (2015)', 'Lab analysis. 280 takeaway samples from 36 outlets across Ireland and Northern Ireland, analysed by Foodtest Laboratories UK (energy, fat, protein, salt). Weighed portions. UK/Irish takeaway versions of dishes.', 'https://safefood.net/admin/getmedia/bca7a58e-5818-4aa0-8dae-a53beb75ac07/whats-in-your-Indian-takeaway_1.aspx?ext=.pdf');
insert into public.food_sources (id, title, method, url) values ('S2', 'USDA Standard Reference, Restaurant Foods: Chinese, chicken chow mein', 'Published reference entry, per 100 g. Accessed through a mirror site, not the USDA database directly.', 'https://getfoodfacts.com/food/restaurant-chinese-chicken-chow-mein-168083');
insert into public.food_sources (id, title, method, url) values ('S3', 'Panda Express, Chow Mein side', 'Chain-published nutrition label, as listed on Fitbit''s food database.', 'https://canarywww.fitbit.com/foods/Chow+Mein/13954683');
insert into public.food_sources (id, title, method, url) values ('S4', 'FatSecret generic entries: Rajma, Rajma Chawal', 'User-contributed database entries with no recipe or oil quantity. Lowest-grade source in this file.', 'https://www.fatsecret.com.sg/calories-nutrition/generic/rajma-chawal');
insert into public.food_sources (id, title, method, url) values ('S5', 'Indian Food Composition Tables 2017 (ICMR-NIN)', 'Primary reference for Indian home-cooked and raw foods. NOT yet extracted into this file. Best base for the home-dish backlog.', 'https://dspace.sduaher.ac.in/jspui/handle/123456789/9077');
insert into public.food_sources (id, title, method, url) values ('S6', 'Tufts University, restaurant and frozen meal calorie accuracy (2010)', 'Lab measurements of 39 restaurant and supermarket items against stated calories. Restaurant items averaged 18% more than stated.', 'https://tuftsjournal.tufts.edu/2010/01_2/briefs/01/');
insert into public.food_sources (id, title, method, url) values ('S7', 'Sunday Times / University of Greenwich lab test of UK chain takeaways', '20 samples. Only half within 20% of declared calories. One roomali roti: 727 kcal measured vs 236 declared.', 'https://foodservicefootprint.com/restaurant-calorie-counts-are-wide-of-the-mark/');
insert into public.foods (legacy_id, name, category, log_mode, default_unit, food_state, region, visible) values ('D001', 'Chicken tikka masala', 'Curry, non-veg', 'dish', 'serving', 'cooked_dish', 'UK_IE', false);
